// ---- Cobalt.tools API (PRIMEIRA TENTATIVA) ----
// URL da instancia propria do Cobalt (hospedada no Railway pela Instructiva)
// Pode ser sobrescrita via env var COBALT_API_URL no Railway
const COBALT_API_URL = (process.env.COBALT_API_URL || 'https://cobalt-production-2fb0.up.railway.app').replace(/\/+$/, '');

function baixarViaCobalt(videoUrl, destPath) {
  return new Promise((resolve, reject) => {
    if (!COBALT_API_URL) return reject(new Error('COBALT_API_URL nao configurada'));
    const body = JSON.stringify({
      url: videoUrl,
      videoQuality: '720',
      filenameStyle: 'basic',
      downloadMode: 'auto'
    });
    const u = new URL(COBALT_API_URL + '/');
    const req = https.request({
      hostname: u.hostname,
      port: u.port || 443,
      path: '/',
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'User-Agent': 'cortador-instructiva/1.0',
        'Content-Length': Buffer.byteLength(body),
      },
      timeout: 45000,
    }, (r) => {
      let data = '';
      r.on('data', chunk => { data += chunk; });
      r.on('end', () => {
        try {
          const j = JSON.parse(data);
          console.log('[cortador] cobalt status:', j.status, '| http:', r.statusCode);
          if ((j.status === 'tunnel' || j.status === 'redirect' || j.status === 'stream') && j.url) {
            // Cobalt retornou URL de download. Baixa o arquivo.
            const baixarArq = (url, redirs) => {
              if ((redirs || 0) > 5) return reject(new Error('Muitos redirects no download'));
              const downloadUrl = new URL(url);
              const proto = downloadUrl.protocol === 'http:' ? require('http') : https;
              proto.get(url, (resp) => {
                if (resp.statusCode >= 300 && resp.statusCode < 400 && resp.headers.location) {
                  return baixarArq(resp.headers.location, (redirs || 0) + 1);
                }
                if (resp.statusCode !== 200) return reject(new Error('HTTP ' + resp.statusCode + ' baixando do tunnel'));
                const out = fs.createWriteStream(destPath);
                resp.pipe(out);
                out.on('finish', () => out.close(() => {
                  const sz = fs.statSync(destPath).size;
                  console.log('[cortador] cobalt OK:', (sz/1024/1024).toFixed(1), 'MB');
                  resolve();
                }));
                out.on('error', reject);
              }).on('error', reject);
            };
            baixarArq(j.url);
          } else if (j.status === 'picker' && j.picker && j.picker.length > 0) {
            // Cobalt deu varias opcoes - pega primeira
            const primeira = j.picker[0];
            if (primeira.url) {
              const baixarPicker = (url) => {
                https.get(url, (resp) => {
                  if (resp.statusCode >= 300 && resp.statusCode < 400 && resp.headers.location) {
                    return baixarPicker(resp.headers.location);
                  }
                  if (resp.statusCode !== 200) return reject(new Error('HTTP ' + resp.statusCode));
                  const out = fs.createWriteStream(destPath);
                  resp.pipe(out);
                  out.on('finish', () => out.close(() => resolve()));
                  out.on('error', reject);
                }).on('error', reject);
              };
              baixarPicker(primeira.url);
            } else {
              reject(new Error('Picker sem URL valida'));
            }
          } else if (j.status === 'error') {
            const code = (j.error && j.error.code) || 'desconhecido';
            reject(new Error('Cobalt: ' + code));
          } else {
            reject(new Error('Resposta Cobalt inesperada: ' + (j.status || JSON.stringify(j).slice(0, 200))));
          }
        } catch (e) {
          reject(new Error('Resposta Cobalt invalida (' + r.statusCode + '): ' + data.slice(0, 200)));
        }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Cobalt timeout (45s)')); });
    req.write(body);
    req.end();
  });
}


// ---- Cache de videos baixados (1 hora) ----
const CACHE_DIR = path.join(os.tmpdir(), 'cortador-cache');
const CACHE_TTL_MS = 60 * 60 * 1000;

function cachePathPara(url, ext) {
  const hash = crypto.createHash('md5').update(url).digest('hex');
  return path.join(CACHE_DIR, hash + '.' + (ext || 'mp4'));
}

function limparCacheAntigo() {
  try {
    if (!fs.existsSync(CACHE_DIR)) return;
    const agora = Date.now();
    for (const f of fs.readdirSync(CACHE_DIR)) {
      const fp = path.join(CACHE_DIR, f);
      try {
        const stat = fs.statSync(fp);
        if (agora - stat.mtimeMs > CACHE_TTL_MS) {
          fs.unlinkSync(fp);
          console.log('[cortador] cache: removido', f, '(velho)');
        }
      } catch (e) {}
    }
  } catch (e) {}
}

function linkValido(u) {
  return typeof u === 'string' && /^https:\/\/(www\.|m\.)?(youtube\.com\/|youtu\.be\/)/.test(u.trim());
}
function tempoValido(t) {
  return typeof t === 'string' && /^(\d{1,2}:)?\d{1,2}:\d{2}$|^\d{1,3}(:\d{2}){0,2}$|^\d+$/.test(t.trim());
}
function paraSegundos(t) {
  const p = String(t).trim().split(':').map(Number);
  if (p.some(isNaN)) return NaN;
  return p.reduce((acc, v) => acc * 60 + v, 0);
}

// ============ AUTENTICAÇÃO ============
// Senha do app (env var APP_PASSWORD, default 'instructiva2026')
const APP_PASSWORD = (process.env.APP_PASSWORD || 'instructiva2026').trim();
// Secret pra assinar o cookie de sessão
const AUTH_SECRET = (process.env.AUTH_SECRET || process.env.ADMIN_KEY || 'instructiva-secret-2026').trim();

function gerarToken() {
  return crypto.createHmac('sha256', AUTH_SECRET).update(APP_PASSWORD).digest('hex');
}

function parseCookies(header) {
  const out = {};
  if (!header) return out;
  header.split(';').forEach(c => {
    const idx = c.indexOf('=');
    if (idx < 0) return;
    const k = c.slice(0, idx).trim();
    const v = c.slice(idx + 1).trim();
    if (k) out[k] = decodeURIComponent(v);
  });
  return out;
}

function autenticado(req) {
  const cookies = parseCookies(req.headers.cookie);
  const token = cookies['instructiva-auth'];
  return token && token === gerarToken();
}

function requireAuth(req, res, next) {
  if (autenticado(req)) return next();
  // Pra requisições de API (JSON), retorna 401
  const wantsJson = (req.headers.accept || '').includes('application/json') || (req.headers['content-type'] || '').includes('application/json');
  if (wantsJson) return res.status(401).json({ erro: 'Nao autenticado', redirect: '/login' });
  // Senão, redireciona pra /login
  return res.redirect('/login');
}

// Rota GET /login: serve a tela bonita
app.get('/login', (req, res) => {
  // Se já autenticado, manda direto pro app
  if (autenticado(req)) return res.redirect('/');
  res.type('html').send(PAGINA_LOGIN);
});

// Rota POST /login: valida senha e seta cookie
app.post('/login', express.json(), (req, res) => {
  const senha = String(req.body.senha || '').trim();
  if (!senha) return res.status(400).json({ erro: 'Digite a senha.' });
  if (senha !== APP_PASSWORD) {
    // Pequeno delay anti brute force
    setTimeout(() => res.status(401).json({ erro: 'Senha incorreta.' }), 600);
    return;
  }
  const token = gerarToken();
  // Cookie válido por 30 dias
  const maxAge = 60 * 60 * 24 * 30;
  res.setHeader('Set-Cookie', `instructiva-auth=${token}; HttpOnly; Path=/; Max-Age=${maxAge}; SameSite=Lax; Secure`);
  res.json({ ok: true, redirect: '/' });
});

// Rota POST /logout: limpa cookie
app.post('/logout', (req, res) => {
  res.setHeader('Set-Cookie', `instructiva-auth=; HttpOnly; Path=/; Max-Age=0; SameSite=Lax; Secure`);
  res.json({ ok: true });
});

