// Helper: roda um comando e retorna {codigo, sinal, stdout, stderr}
function executar(cmd, args, label) {
  return new Promise((resolve) => {
    console.log('[cortador]', label, 'iniciando...');
    const proc = spawn(cmd, args);
    let stdout = '';
    let stderr = '';
    proc.stdout.on('data', d => { stdout += d.toString(); });
    proc.stderr.on('data', d => { stderr += d.toString(); });
    proc.on('close', (codigo, sinal) => {
      console.log('[cortador]', label, 'terminou com codigo', codigo, 'sinal', sinal);
      if (stderr) console.log('[cortador] stderr de', label + ':\n' + stderr.slice(-1500));
      resolve({ codigo, sinal, stdout, stderr });
    });
    proc.on('error', (err) => {
      resolve({ codigo: -1, sinal: null, stdout: '', stderr: 'erro ao executar: ' + err.message });
    });
  });
}

// Rota /cortar: aceita JSON (URL YouTube) ou multipart/form-data (upload arquivo)
app.post('/cortar', requireAuth, (req, res) => {
  const ct = req.headers['content-type'] || '';
  if (ct.includes('multipart/form-data')) {
    upload.single('arquivo')(req, res, (err) => {
      if (err) {
        const msg = err.code === 'LIMIT_FILE_SIZE' ? 'Arquivo muito grande (max 2GB).' : 'Erro no upload: ' + err.message;
        return res.status(400).json({ erro: msg });
      }
      processarCorte(req, res);
    });
  } else {
    processarCorte(req, res);
  }
});

async function processarCorte(req, res) {
  const isUpload = !!req.file;
  const url = isUpload ? '' : (req.body.url || '').trim();
  const inicio = String(req.body.inicio || '').trim();
  const fim = String(req.body.fim || '').trim();
  const formato = String(req.body.formato || 'original').trim();
  const texto = String(req.body.texto || '').trim().slice(0, 80);
  const watermark = String(req.body.watermark || '').trim() === 'true' || req.body.watermark === true;

  function limparUpload() {
    if (isUpload && req.file) { try { fs.unlinkSync(req.file.path); } catch(_) {} }
  }
  function erroResp(status, json) {
    limparUpload();
    return res.status(status).json(json);
  }

  if (!isUpload && !linkValido(url)) return erroResp(400, { erro: 'Cole um link valido do YouTube ou anexe um arquivo.' });
  if (!['original', 'centro_blur', 'crop', 'talking_texto'].includes(formato)) return erroResp(400, { erro: 'Formato invalido.' });

  // Tempos obrigatorios pra YouTube, opcionais pra arquivo (se vazio processa tudo)
  const temTempos = !!(inicio && fim);
  if (!isUpload && !temTempos) return erroResp(400, { erro: 'Preenche os dois campos de tempo.' });
  if (temTempos && (!tempoValido(inicio) || !tempoValido(fim))) return erroResp(400, { erro: 'Use o formato de tempo certo, tipo 4:32 ou 1:04:10.' });

  const si = temTempos ? paraSegundos(inicio) : 0;
  const sf = temTempos ? paraSegundos(fim) : 0;
  if (temTempos) {
    if (isNaN(si) || isNaN(sf) || sf <= si) return erroResp(400, { erro: 'O fim precisa ser depois do inicio.' });
    if (sf - si > MAX_SEGUNDOS) return erroResp(400, { erro: 'O corte ta muito longo (maximo 60 minutos por vez).' });
  }

  let pasta;
  try {
    if (!isUpload) await garantirYtdlp();
    await garantirFfmpeg();
    if (formato === 'talking_texto' && texto) await garantirFonte();
    pasta = fs.mkdtempSync(path.join(os.tmpdir(), 'corte-'));
    const cortePath = path.join(pasta, 'corte.mp4');
    const duracao = temTempos ? (sf - si) : 0;
    let fullPath;
    let cacheHit = false;

    if (isUpload) {
      fullPath = req.file.path;
      console.log('[cortador] upload local recebido:', req.file.originalname, '(' + (req.file.size / 1024 / 1024).toFixed(1) + ' MB)');
    } else {
      fs.mkdirSync(CACHE_DIR, { recursive: true });
      limparCacheAntigo();
      fullPath = cachePathPara(url, 'mp4');
      cacheHit = fs.existsSync(fullPath) && (() => { try { return fs.statSync(fullPath).size > 1024 * 1024; } catch (e) { return false; } })();

    if (cacheHit) {
      console.log('[cortador] CACHE HIT - usando video ja baixado:', path.basename(fullPath));
    } else {
      const tDownload = Date.now();
      console.log('[cortador] CACHE MISS - tentando Cobalt primeiro |', COBALT_API_URL);

      let cobaltErro = null;
      let cobaltOk = false;

      // TENTATIVA 1: Cobalt proprio (rapido, confiavel)
      if (COBALT_API_URL) {
        try {
          await baixarViaCobalt(url, fullPath);
          if (fs.existsSync(fullPath) && fs.statSync(fullPath).size > 1024 * 1024) {
            cobaltOk = true;
            console.log('[cortador] Cobalt baixou em', ((Date.now()-tDownload)/1000).toFixed(1), 's');
          } else {
            throw new Error('arquivo muito pequeno');
          }
        } catch (e) {
          cobaltErro = e.message;
          console.log('[cortador] Cobalt falhou:', e.message, '- tentando yt-dlp como fallback...');
          try { if (fs.existsSync(fullPath)) fs.unlinkSync(fullPath); } catch (e2) {}
        }
      }

      // TENTATIVA 2: yt-dlp como fallback (5 estrategias)
      let r1 = null;
      if (!cobaltOk) {
        const estrategias = [
          { ext: 'youtube:player_client=mweb,tv_embedded,web_safari', fmt: 'bv*[height<=720]+ba/b[height<=720]/best' },
          { ext: 'youtube:player_client=ios,android',                  fmt: 'best[height<=720]/best' },
          { ext: 'youtube:player_client=tv,web_safari,default',        fmt: null },
          { ext: 'youtube:player_client=web,web_safari',               fmt: null },
          { ext: 'youtube:player_client=mweb',                         fmt: 'best' },
        ];
        for (let i = 0; i < estrategias.length; i++) {
          const { ext, fmt } = estrategias[i];
          console.log('[cortador] yt-dlp tentativa', i+1, '| extractor:', ext, '| fmt:', fmt || 'auto');
          const args = [
            '--no-playlist', '--no-warnings', '--no-progress',
            '--extractor-args', ext,
            ...(cookiesOk ? ['--cookies', COOKIES_PATH] : []),
            ...(PROXY_URL ? ['--proxy', PROXY_URL] : []),
            '--ffmpeg-location', FFMPEG,
            '-N', '4',
            '--retries', '2',
            ...(fmt ? ['-f', fmt] : []),
            '--merge-output-format', 'mp4',
            '-o', fullPath,
            url,
          ];
          r1 = await executar(YTDLP, args, 'yt-dlp-download');
          if (r1.codigo === 0 && fs.existsSync(fullPath) && fs.statSync(fullPath).size > 1024 * 1024) {
            console.log('[cortador] yt-dlp OK na tentativa', i+1);
            break;
          }
          try { if (fs.existsSync(fullPath)) fs.unlinkSync(fullPath); } catch (e) {}
        }
      }

      const dt1 = ((Date.now() - tDownload) / 1000).toFixed(1);
      console.log('[cortador] download total levou', dt1, 's | cobaltOk:', cobaltOk);

      if (!fs.existsSync(fullPath) || fs.statSync(fullPath).size <= 1024 * 1024) {
        try { if (fs.existsSync(fullPath)) fs.unlinkSync(fullPath); } catch (e) {}
        limpar(pasta);
        const detalheYtdlp = (r1 && (r1.stderr || r1.stdout) || 'nao tentado').slice(-400);
        const detalhe = `cobalt: ${cobaltErro || 'nao tentado'}\n\nyt-dlp: ${detalheYtdlp}`;
        return res.status(500).json({
          erro: 'Nao consegui baixar esse video por nenhum metodo. Tenta upload de arquivo.',
          detalhe
        });
      }
    }
    } // fim else do isUpload

    const t2 = Date.now();
    console.log('[cortador] cortando | formato', formato, '| inicio', si, 's | duracao', duracao, 's');

    let cutArgs;
    if (formato === 'original') {
      // -c copy: cut rapido sem reencode (segundos)
      cutArgs = [
        '-y',
        ...(temTempos ? ['-ss', String(si)] : []),
        '-i', fullPath,
        ...(temTempos ? ['-t', String(duracao)] : []),
        '-c', 'copy',
        '-avoid_negative_ts', 'make_zero',
        cortePath,
      ];
    } else {
      // Formatos verticais: reencode com filtro
      let filtroV;
      if (formato === 'centro_blur') {
        // Vídeo no centro com fundo desfocado
        filtroV = 'split=2[a][b];[a]scale=720:1280:force_original_aspect_ratio=increase,crop=720:1280,boxblur=20:1[bg];[b]scale=720:-1[fg];[bg][fg]overlay=(W-w)/2:(H-h)/2';
      } else if (formato === 'crop') {
        // Crop central, zoom no meio
        filtroV = 'crop=ih*9/16:ih,scale=720:1280';
      } else { // talking_texto
        // Se nao tem texto, vira so um crop vertical limpo (sem subtitles filter)
        if (!texto) {
          filtroV = 'crop=ih*9/16:ih,scale=720:1280';
        } else {
          // Crop + texto via subtitles ASS (drawtext nao disponivel no build do ffmpeg)
          // libass renderiza com fontes apontadas via fontsdir
          const assPath = path.join(pasta, 'texto.ass');
          const textoUp = texto.toUpperCase().replace(/[\\{}]/g, '');
          const assConteudo = `[Script Info]
ScriptType: v4.00+
PlayResX: 720
PlayResY: 1280
ScaledBorderAndShadow: yes

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Anton,62,&H00FFFFFF,&H00FFFFFF,&H00000000,&HA0000000,1,0,0,0,100,100,0,0,3,4,1,2,30,30,140,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:00.00,9:00:00.00,Default,,0,0,0,,${textoUp}
`;
          fs.writeFileSync(assPath, assConteudo);
          const assPathEscaped = assPath.replace(/\\/g, '/').replace(/:/g, '\\\\:').replace(/,/g, '\\,');
          const fontsDir = path.dirname(FONTE);
          filtroV = `crop=ih*9/16:ih,scale=720:1280,subtitles='${assPathEscaped}':fontsdir='${fontsDir}'`;
        }
      }
      // Watermark Instructiva: usa filter_complex com 2 inputs (video + logo)
      const usarWatermark = watermark && logoPronta;
      if (usarWatermark) {
        // Logo no canto inferior direito, 90px (11% da largura), margem 24px
        const filterComplex = `[0:v]${filtroV}[vmain];[1:v]scale=90:90[wm];[vmain][wm]overlay=W-w-24:H-h-24[vout]`;
        cutArgs = [
          '-y',
          ...(temTempos ? ['-ss', String(si)] : []),
          '-i', fullPath,
          '-i', LOGO_PATH,
          ...(temTempos ? ['-t', String(duracao)] : []),
          '-filter_complex', filterComplex,
          '-map', '[vout]',
          '-map', '0:a?',
          '-c:v', 'libx264',
          '-preset', 'ultrafast',
          '-crf', '23',
          '-c:a', 'aac',
          '-b:a', '128k',
          '-movflags', '+faststart',
          cortePath,
        ];
      } else {
        cutArgs = [
          '-y',
          ...(temTempos ? ['-ss', String(si)] : []),
          '-i', fullPath,
          ...(temTempos ? ['-t', String(duracao)] : []),
          '-vf', filtroV,
          '-c:v', 'libx264',
          '-preset', 'ultrafast',
          '-crf', '23',
          '-c:a', 'aac',
          '-b:a', '128k',
          '-movflags', '+faststart',
          cortePath,
        ];
      }
    }

    const r2 = await executar(FFMPEG, cutArgs, 'ffmpeg-cut');
    const dt2 = ((Date.now() - t2) / 1000).toFixed(1);
    console.log('[cortador] cut levou', dt2, 's | cache:', cacheHit ? 'HIT' : (isUpload ? 'UPLOAD' : 'MISS'), '| formato:', formato);

    // Apos ffmpeg terminar, pode deletar o upload (se houver)
    limparUpload();

    if (r2.codigo !== 0 || !fs.existsSync(cortePath)) {
      limpar(pasta);
      return res.status(500).json({ erro: 'Baixei o video mas nao consegui cortar.', detalhe: (r2.stderr || 'sem detalhes').slice(-600) });
    }

    const nomeDownload = temTempos
      ? `corte_${inicio.replace(/:/g, '-')}_a_${fim.replace(/:/g, '-')}.mp4`
      : `video_${formato}.mp4`;
    res.download(cortePath, nomeDownload, () => limpar(pasta));
  } catch (e) {
    limparUpload();
    if (pasta) limpar(pasta);
    res.status(500).json({ erro: 'Deu um erro no servidor.', detalhe: String(e.message || e) });
  }
}

function limpar(pasta) { try { fs.rmSync(pasta, { recursive: true, force: true }); } catch (e) {} }

const PORTA = process.env.PORT || 3000;
app.listen(PORTA, () => console.log('Cortador rodando na porta ' + PORTA));
